suppressPackageStartupMessages({library(ggpubr); library(rstatix); library(dplyr)})
D <- "F:/OpenScience/audits/bio-data-visualization-statistical-annotation"
rd <- function(n) read.csv(file.path(D, "data", paste0(n, ".csv")))
bd <- rd("border"); bd$group <- factor(bd$group)
lab <- function(p, layer = length(ggplot_build(p)$data)) { g <- ggplot_build(p)$data[[layer]]; as.character(if ("label" %in% names(g)) g$label else g$annotation) }
cat("### A. ggpubr honours p.adjust.method only WITHOUT comparisons (ref.group route)\n")
p <- ggboxplot(bd, x="group", y="value") + stat_compare_means(method="wilcox.test", label="p.signif", p.adjust.method="holm", ref.group="G1")
print(lab(p)); 
cm <- compare_means(value ~ group, bd, method="wilcox.test", p.adjust.method="holm", ref.group="G1"); print(cm[, c("group1","group2","p","p.adj","p.signif")])
p <- ggboxplot(bd, x="group", y="value") + stat_compare_means(method="wilcox.test", label="p.signif", p.adjust.method="holm", ref.group="G1", comparisons=list(c("G1","G2"), c("G1","G3")))
cat("with comparisons AND ref.group:", lab(p), "\n")
cat("### B. Skill block-2 pattern vs adjusted truth on border data (raw stars vs Holm stars)\n")
raw <- c(wilcox.test(bd$value[bd$group=="G1"], bd$value[bd$group=="G2"])$p.value, wilcox.test(bd$value[bd$group=="G1"], bd$value[bd$group=="G3"])$p.value, wilcox.test(bd$value[bd$group=="G2"], bd$value[bd$group=="G3"])$p.value)
sig <- function(p) as.character(cut(p, c(0,1e-4,1e-3,1e-2,5e-2,1), labels=c("****","***","**","*","ns"), right=TRUE))
cat("shown by Skill pattern:", lab(ggboxplot(bd, x="group", y="value") + stat_compare_means(method='wilcox.test', comparisons=list(c("G1","G2"),c("G1","G3"),c("G2","G3")), label='p.signif', p.adjust.method='holm')), "\n")
cat("raw stars:", sig(raw), " Holm stars:", sig(p.adjust(raw,"holm")), "\n")
cat("### C. Dunn post-hoc: rstatix::dunn_test vs manual Dunn (tie-corrected), Holm\n")
tg <- rd("three_group"); tg$group <- factor(tg$group)
dn <- tg %>% dunn_test(value ~ group, p.adjust.method="holm"); print(dn[, c("group1","group2","statistic","p","p.adj")])
r <- rank(tg$value); N <- nrow(tg); ni <- table(tg$group); rb <- tapply(r, tg$group, mean); tie <- table(tg$value); C <- 1 - sum(tie^3 - tie)/(N^3 - N)
man <- combn(levels(tg$group), 2, function(g) { z <- (rb[g[1]] - rb[g[2]]) / sqrt((N*(N+1)/12) * C * (1/ni[g[1]] + 1/ni[g[2]])); c(z=unname(z), p=2*pnorm(-abs(z))) })
cat("manual z:", signif(man["z",],5), " p:", signif(man["p",],5), " holm:", signif(p.adjust(man["p",],"holm"),5), "\n")
cat("### D. p.adjust 'fdr' == 'BH'\n"); print(all.equal(p.adjust(raw,"fdr"), p.adjust(raw,"BH")))
cat("### E. FWER numbers in SKILL\n"); print(round(1-0.95^c(3,6,15),3))
cat("### F. Tukey path in decision tree (rstatix::tukey_hsd) on four_group\n")
fd <- rd("four_group"); th <- fd %>% tukey_hsd(value ~ group); print(th[, c("group1","group2","p.adj","p.adj.signif")]); print(TukeyHSD(aov(value~group, fd))$group[, "p adj"])
